INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '循环上岗型', 'kp-eng-s-loop', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "循环上岗型"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "类似于工厂的三班倒，总有固定数量的人在岗，但人员不断轮替。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "比如：“5个工人负责3台机器，每台机器必须有人看管，工人轮流休息。总共工作 10 小时”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题：工时守恒定律"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不要去画复杂的排班表！直接从宏观角度算“机器总共消耗了多少工时”，然后平摊给所有工人。"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{每人工作时间} = \\frac{\\text{机器数} \\times \\text{总运转时间}}{\\text{总人数}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[识别出是固定机器/岗位, 多人轮流的题型] --> B[完全不需要考虑怎么排班]\nB --> C[计算机器需要的总工时 = 机器数 × 运转时间]\nC --> D[总工时必定由所有工人平摊]\nD --> E[用总工时 ÷ 总人数 = 每个人实际干活的时间]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 某车间有 3 台机器需要操作，现有 5 名工人。要求机器不停，工人轮流上岗且休息时间相等。若这批机器需连续运转 10 小时，每个工人休息了几小时？选项：A. 2  B. 3  C. 4  D. 6"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算总工时：3 台机器，每台转 10 小时。总共需要消耗 3 × 10 = 30 个机器工时。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "平摊工时：这 30 个工时由 5 名工人承担。因为要求“休息时间相等”，即工作时间也相等。每名工人实际工作时间 = 30 ÷ 5 = 6 小时。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算休息时间：总运转 10 小时，工作了 6 小时，所以每人休息了 10 - 6 = 4 小时。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定答案：选 C。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "强行画排班表：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "在考场上试图用 A,B,C,D,E 五个人去填满 3 个格子的 10 个时间段，绝对是自寻死路。统筹与工程结合的最高境界就是抓住“能量守恒（工时守恒）”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "死记硬背公式：人均工作时间 = 岗位数 × 总时长 ÷ 总人数。看到这类题直接秒杀。"}]}]}$$ AS jsonb), NULL, '循环上岗型的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "循环上岗型"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_s_loop", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
